  if(t.hasAttribute("data-image-up")||t.hasAttribute("data-image-down")||t.hasAttribute("data-image-remove")){let rows=imageGalleryRows();const index=Number(t.dataset.imageUp??t.dataset.imageDown??t.dataset.imageRemove);if(t.hasAttribute("data-image-remove"))rows.splice(index,1);else{const next=index+(t.hasAttribute("data-image-up")?-1:1);if(next>=0&&next<rows.length)[rows[index],rows[next]]=[rows[next],rows[index]];}saveImageGallery(rows);return;}
